import http from 'node:http';
const jobs=new Map();const calls=[];let sequence=0;
const creator=id=>({platform:'youtube',profileUrl:`http://wave-fixture:8087/creator/${id}`,displayName:`受控夹具 ${id}`,followerCount:null,region:null,evidence:[{url:`http://wave-fixture:8087/creator/${id}`,kind:'profile',provider:'qa-controlled-fixture',text:'这是受控验收账号，公开主页供真实浏览器核验。不是 WaveSurge 实际发现的社交账号。'}],fixture:true});
const server=http.createServer(async(req,res)=>{
 const url=new URL(req.url,'http://wave-fixture:8087');
 if(url.pathname.startsWith('/api/v1/'))calls.push({path:req.url,method:req.method});
 const json=value=>{res.writeHead(200,{'content-type':'application/json'});res.end(JSON.stringify(value));};
 if(url.pathname==='/api/v1/discover/db'){json({creators:[creator('alice'),creator('bob')],fixture:true});return;}
 if(url.pathname==='/api/v1/instagram/v3/search_users'){json({code:200,data:{users:[{username:'qa_alice',id:'12345678901234567890'},{username:'qa_alice',id:'12345678901234567890'}],items:[{username:'ignored'}],rank_token:null}});return;}
 if(url.pathname==='/api/v1/instagram/v1/fetch_user_info_by_username_v2'){json({code:200,data:{id:'12345678901234567890',username:'qa_alice',full_name:'受控 Instagram 技术研究夹具',biography:'I create original technology and headphones tutorials. Based in United States.',edge_followed_by:{count:20400},is_private:false,is_verified:false}});return;}
 if(url.pathname==='/api/v1/instagram/v1/fetch_user_posts'){json({code:200,data:{items:[{id:'4000000000000000001_12345678901234567890',code:'qa_code',media_type:1,taken_at:1791504000,caption:{text:'Original public headphone and processor technology tutorial. This is a controlled fixture, not a real Instagram account.'},like_count:100,comment_count:20,image_versions2:{candidates:[{width:100,url:'http://wave-fixture:8087/media/qa-photo.svg'},{width:1080,url:'http://wave-fixture:8087/media/qa-photo.svg'}]}}],more_available:!url.searchParams.has('max_id'),next_max_id:url.searchParams.has('max_id')?null:'opaque_12345678901234567890'}});return;}
 if(url.pathname==='/api/v1/instagram/v2/fetch_post_info'){json({code:200,data:{data:{id:'4000000000000000001',code:'qa_code',media_type:1,taken_at:1791504000,caption:{text:'Original technology tutorial demonstrating noise cancelling headphones and processors. Controlled fixture.'},metrics:{like_count:120,comment_count:20},image_versions:{items:[{width:1080,url:'http://wave-fixture:8087/media/qa-photo.svg'}]}}}});return;}
 if(url.pathname==='/fixture-calls'){json(calls);return;}
 if(url.pathname==='/media/qa-photo.svg'){res.writeHead(200,{'content-type':'image/svg+xml'});res.end('<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="800"><rect width="1080" height="800" fill="#e8e8dd"/><text x="80" y="100" font-size="40">CONTROLLED HEADPHONES TECHNOLOGY PHOTO</text><path d="M300 500 V350 C300 150 780 150 780 350 V500" fill="none" stroke="#123427" stroke-width="60"/><rect x="260" y="420" width="100" height="220" rx="25" fill="#123427"/><rect x="720" y="420" width="100" height="220" rx="25" fill="#123427"/></svg>');return;}

 if(req.url==='/api/v1/creator-search/requests'&&req.method==='POST'){let raw='';for await(const chunk of req)raw+=chunk;const body=JSON.parse(raw);const id=`controlled-${++sequence}`;jobs.set(id,{body,polls:0});res.writeHead(201,{'content-type':'application/json'});res.end(JSON.stringify({taskId:id}));return;}
 if(req.url.startsWith('/api/v1/creator-search/requests/')){const job=jobs.get(req.url.split('/').at(-1));if(!job){res.writeHead(404);res.end('{}');return;}job.polls++;res.writeHead(200,{'content-type':'application/json'});res.end(JSON.stringify({status:job.polls===1?'running':'done',creators:job.polls===1?[creator('alice')]:[creator('alice'),creator('bob')],alsoFound:job.polls===1?[]:[creator('alice')],fixture:true}));return;}
 if(req.url==='/fixture-state'){res.writeHead(200,{'content-type':'application/json'});res.end(JSON.stringify([...jobs].map(([id,j])=>({id,...j}))));return;}
 if(req.url.startsWith('/creator/')){const alice=req.url.includes('alice');res.writeHead(200,{'content-type':'text/html; charset=utf-8'});res.end(`<!doctype html><title>公开研究夹具 ${alice?'Alice':'Bob'}</title><style>body{font:22px/1.8 sans-serif;background:#f1f4ec;color:#132a20;padding:60px}article{border:2px solid #6b8267;padding:30px}strong{font-size:35px}</style><h1>${alice?'Alice':'Bob'} — controlled test creator, NOT a real social account</h1><p>${alice?'20.4K':'67.6K'} subscribers</p><p>Location: United States</p><p>${alice?'Technology tutorials, productivity tools and student study workflows.':'Technology education and headphone reviews.'}</p><article><strong>CHIP / CIRCUIT BOARD / HEADPHONES</strong><p>Original public technology tutorial, published October 9, 2026. Explains processors and noise cancellation.</p><p>${alice?'Presentation style: clear step-by-step teacher explanation, everyday casual clothing. There is no evidence of geek fashion.':'Presentation style: detailed geek technology enthusiast tutorials and gadget demonstrations.'}</p></article>${alice?'<article><strong>STUDY WORKFLOW / NOTION / POMODORO</strong><p>Original public study efficiency tutorial, published October 8, 2026. For university students: organize lecture notes and assignment deadlines in Notion, use a 25-minute Pomodoro focus block, then test recall with flashcards to reduce distracted study time. Demonstrates the complete study planning workflow step by step.</p><p>Presentation style: practical teacher explanation and on-screen productivity walkthrough.</p></article>':''}`);return;}
 res.writeHead(404);res.end('Not found');
});server.listen(8087,'0.0.0.0');
